                        "pattern": "Present Participle (Verb-ing)..., Main Clause",
                        "meaning": "Ayni vaqtdagi holat yoki sababni ifodalash (birgalikdagi harakat)",
                        "usageNotes": "Ikkala qismning egasi aynan bir xil shaxs yoki narsa bo'lishi shart.",
