                        "exampleSentence": "Neuroplasticity allows individuals to recover lost linguistic faculties following severe strokes.",
                        "exampleTranslation": "Neyroplastiklik odamlarga og'ir insultdan so'ng yo'qolgan nutq qobiliyatini tiklash imkonini beradi."
